var l={name:`Plank`,description:`Statikus tartás alkartámaszban. Edzi a törzsizmokat és a törzs stabilitását.`,steps:[`Támaszkodj az alkarodra, a könyök a váll alatt.`,`Nyújtsd ki a lábadat, és egyenesítsd ki a testedet a sarkadtól a fejedig.`,`Feszítsd meg a hasadat és a farizmodat.`,`Tartsd a helyzetet a megadott ideig, egyenletesen lélegezve.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban vagy a derekadban.`],techniqueNotes:[`Ne told fel és ne ereszd le a csípődet.`,`Ne tartsd vissza a lélegzetedet.`]};var t={name:`Superman`,description:`Karok és lábak egyidejű emelése hasra fekve. Edzi a hátizmokat és a farizmot.`,steps:[`Feküdj hasra, a karodat nyújtsd előre.`,`Egyszerre emeld meg egy kicsit a karodat, a mellkasodat és a lábadat a talaj fölé.`,`Tarts ki 1–2 másodpercig.`,`Lassan ereszkedj vissza.`],warnings:[`Ne emelkedj hirtelen és túl magasra.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`A tekinteted lefelé irányul, a nyak a gerinccel egy vonalban.`,`Simán mozogj, rángatás nélkül.`]};var s={name:`Burpee`,description:`Összetett gyakorlat: guggolás, fekvőtámasz helyzet, visszatérés és felugrás. Fejleszti az általános állóképességet és az egész testet terheli.`,steps:[`Guggolj le, és tedd a tenyeredet a talajra.`,`Told hátra a lábadat fekvőtámasz helyzetbe.`,`Húzd vissza a lábadat a kezedhez, és egyenesedj fel.`,`Végezz egy kis felugrást, a karod a fejed fölött.`],warnings:[`Puhán érkezz, és fekvőtámasz helyzetben ne homorítsd a derekadat.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel az ízületeidben vagy a hátadban.`],techniqueNotes:[`Fekvőtámasz helyzetben tartsd egyenesen a testedet.`,`A kontrollra törekedj, ne a maximális sebességre.`]};var d={"bodyweight-squat":{name:`Guggolás saját testsúllyal`,description:`Alap guggolás külső súly nélkül. Edzi a combfeszítőt és a farizmot, fejleszti a térd és a csípő mozgáskontrollját.`,steps:[`Állj egyenesen, a lábfejek vállszélességben.`,`Told hátra a csípődet, és hajlítsd be a térdedet, miközben lefelé ereszkedsz.`,`Ereszkedj le kényelmes mélységig, a hátadat egyenesen tartva.`,`Told el magad a talpaddal, és térj vissza a kiindulóhelyzetbe.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`A térd a lábujjak irányába mozog.`,`Ne emeld fel a sarkadat a talajról.`]},"split-squat":{name:`Kitöréses guggolás helyben`,description:`Guggolás széles lépéshelyzetben. Külön-külön edzi mindkét láb combfeszítőjét és farizmát, és javítja az egyensúlyt.`,steps:[`Állj széles kitörésbe: az egyik láb elöl, a másik hátul.`,`Ereszkedj függőlegesen lefelé, miközben mindkét térdedet behajlítod.`,`Told fel magad az elülső lábaddal.`,`Végezd el az összes ismétlést, majd cserélj lábat.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`Tartsd a törzsedet függőlegesen.`,`A testsúly főleg az elülső lábon van.`]},"reverse-lunge":{name:`Hátrafelé kitörés`,description:`Kitörés hátralépéssel. Edzi a combfeszítőt és a farizmot, fejleszti az egyensúlyt és a koordinációt.`,steps:[`Állj egyenesen, a lábfejek csípőszélességben.`,`Lépj hátra, és ereszkedj le mindkét térded behajlításával.`,`Told el magad az elülső lábaddal, és térj vissza a kiindulóhelyzetbe.`,`Cserélgesd a lábakat, vagy végezd az összes ismétlést az egyik oldalra.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`A hátralépést kontrolláltan végezd, rántás nélkül.`,`Tartsd egyenesen a törzsedet.`]},"glute-bridge":{name:`Farizomhíd`,description:`Csípőemelés hanyatt fekve. Edzi a farizmot és a comb hátsó oldalát.`,steps:[`Feküdj hanyatt, hajlítsd be a térdedet, a talpad a talajon.`,`Feszítsd meg a farizmodat, és told fel a csípődet.`,`Tarts ki egy másodpercig a felső ponton.`,`Lassan engedd vissza a csípődet a talajra.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`A felső ponton ne homorítsd a derekadat.`,`Told a sarkaddal a talajt.`]},"single-leg-glute-bridge":{name:`Egylábas farizomhíd`,description:`A farizomhíd nehezített változata, egy lábra támaszkodva. Edzi a farizmot és a comb hátsó oldalát, javítja a medence stabilitását.`,steps:[`Feküdj hanyatt, hajlítsd be a térdedet, a talpad a talajon.`,`Nyújtsd ki az egyik lábadat, és emeld a talaj fölé.`,`Emeld fel a csípődet a támasztó láb sarkával nyomva.`,`Lassan ereszkedj vissza; a sorozat után cserélj lábat.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`Tartsd egyenesen a csípődet, ne billentsd el.`,`Lassan és kontrolláltan mozogj.`]},"knee-push-up":{name:`Térdelő fekvőtámasz`,description:`A fekvőtámasz könnyített változata térden támaszkodva. Edzi a mellizmot és a tricepszet.`,steps:[`Térdelj le, a tenyered a talajon, kicsit szélesebben a vállnál.`,`Egyenesítsd ki a testedet a térdedtől a fejedig.`,`Hajlítsd be a karodat, és ereszd a mellkasodat a talajhoz.`,`Told el magad, és nyújtsd ki a karodat.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a csuklódban vagy a vállaidban.`],techniqueNotes:[`A könyök nagyjából 45°-os szöget zár be a törzzsel.`,`Ne ereszd le a derekadat.`]},"push-up":{name:`Fekvőtámasz`,description:`Klasszikus fekvőtámasz a talajon. Edzi a mellizmot, a tricepszet és a törzs stabilizátorait.`,steps:[`Vegyél fel fekvőtámasz helyzetet, a tenyér kicsit szélesebben a vállnál.`,`Egyenesítsd ki a testedet a sarkadtól a fejedig.`,`Hajlítsd be a karodat, és ereszd a mellkasodat a talajhoz.`,`Told el magad, és nyújtsd ki a karodat.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a csuklódban vagy a vállaidban.`],techniqueNotes:[`Tartsd feszesen a hasadat és a farizmodat.`,`A könyök nagyjából 45°-os szöget zár be a törzzsel.`]},"wall-push-up":{name:`Fekvőtámasz falnál`,description:`A fekvőtámasz legkönnyebb változata, falra támaszkodva. Minimális terheléssel edzi a mellizmot és a tricepszet.`,steps:[`Állj a fal felé fordulva, karnyújtásnyi távolságra.`,`Támaszkodj a tenyereddel a falnak vállmagasságban.`,`Hajlítsd be a karodat, és közelítsd a mellkasodat a falhoz.`,`Told el magad, és térj vissza a kiindulóhelyzetbe.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban.`],techniqueNotes:[`Tartsd egyenesen a testedet, mint egy deszkát.`,`Minél távolabb vannak a lábfejek a faltól, annál nehezebb.`]},"pike-push-up":{name:`Csuklyás fekvőtámasz (pike)`,description:`Fekvőtámasz felemelt csípővel, amely a terhelést a vállakra helyezi át. Edzi a deltaizmot és a tricepszet.`,steps:[`Vegyél fel fekvőtámasz helyzetet, és told fel a csípődet, hogy fordított „V” betűt formázz.`,`Hajlítsd be a karodat, és ereszd a fejedet a talaj felé a tenyered között.`,`Told el magad, és nyújtsd ki a karodat.`,`Tartsd magasan a csípődet az egész sorozat alatt.`],warnings:[`Lassan ereszkedj, és ne támaszkodj a fejeddel a talajra.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban, a csuklódban vagy a nyakadban.`],techniqueNotes:[`A könyök hátrafelé mutat, nem oldalra.`,`A tekinteted a talajra irányul a tenyered között.`]},plank:l,"side-plank":{name:`Oldalsó plank`,description:`Statikus oldalsó tartás alkartámaszban. Edzi a ferde hasizmokat és a törzs stabilizátorait.`,steps:[`Feküdj az oldaladra, a könyököd a válladad alatt.`,`Tedd a lábfejeidet egymásra, vagy az egyiket a másik elé.`,`Told fel a csípődet, hogy a tested egy vonalba kerüljön.`,`Tartsd a helyzetet a megadott ideig, majd cserélj oldalt.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a válladban.`],techniqueNotes:[`Ne hagyd, hogy a csípőd lelógjon.`,`A nyakadat tartsd a testtel egy vonalban.`]},"dead-bug":{name:`Döglött bogár`,description:`Ellentétes kar és láb váltakozó kinyújtása hanyatt fekve. Edzi a mély törzsizmokat és a derék helyzetének kontrollját.`,steps:[`Feküdj hanyatt, a karod nyújtsd a magasba, a lábadat hajlítsd derékszögben.`,`Lassan ereszd a talaj felé az ellentétes kart és lábat.`,`Vidd vissza őket a kiindulóhelyzetbe.`,`Ismételd meg a másik kar-láb párral.`],warnings:[],techniqueNotes:[`Nyomd a derekadat a talajhoz.`,`Lassan mozogj, kilégzéssel ereszkedj.`]},"bird-dog":{name:`Madár-kutya`,description:`Ellentétes kar és láb váltakozó kinyújtása négykézláb. Edzi a törzsizmokat, a farizmot és a koordinációt.`,steps:[`Állj négykézlábra: a tenyered a váll alatt, a térded a csípő alatt.`,`Egyszerre nyújtsd előre az egyik karodat és hátra az ellentétes lábadat.`,`Tarts ki egy másodpercig.`,`Térj vissza a kiindulóhelyzetbe, és cserélj oldalt.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a csuklódban.`],techniqueNotes:[`Tartsd egyenesen a hátadat, ne homoríts.`,`A csípő párhuzamos marad a talajjal.`]},superman:t,"wall-sit":{name:`Falnál ülés`,description:`Statikus tartás ülő helyzetben a falnak támaszkodva. Edzi a combfeszítőt és a láb állóképességét.`,steps:[`Állj háttal a falnak, a lábfejek nagyjából fél méterre tőle.`,`Csúsztasd lefelé a hátadat, amíg a térded kényelmes szögben be nem hajlik.`,`Tartsd a helyzetet a megadott ideig.`,`Lassan told fel magad.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`A térd a boka fölött van, nem megy túl a lábujjakon.`,`A hátad teljesen a falhoz simul.`]},"jumping-jacks":{name:`Terpesz-zár ugrás`,description:`Ugrás a karok és a lábak egyidejű széttárásával. Fejleszti a szív- és érrendszeri állóképességet, és átmelegíti az egész testet.`,steps:[`Állj egyenesen, a lábad összezárva, a karod a test mellett.`,`Ugrással told szét a lábadat, és emeld a karodat a fejed fölé.`,`Ugrással térj vissza a kiindulóhelyzetbe.`,`Folytasd egyenletes tempóban a megadott ideig.`],warnings:[`Puhán érkezz a talp elülső részére.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben vagy a bokádban.`],techniqueNotes:[`Landoláskor a térd enyhén behajlítva.`,`Lélegezz egyenletesen.`]},"step-jacks":{name:`Terpesz-zár lépésekkel`,description:`Ugrás nélküli terpesz-zár: oldalra lépés a karok fej fölé emelésével. Átmelegíti a testet és ugrás nélkül emeli a pulzust.`,steps:[`Állj egyenesen, a lábad összezárva, a karod a test mellett.`,`Lépj oldalra, és közben emeld a karodat a fejed fölé.`,`Zárd vissza a lábadat, és ereszd le a karodat.`,`Váltogasd az oldalakat egyenletes tempóban.`],warnings:[],techniqueNotes:[`Olyan tempót tarts, hogy a pulzusod mérsékelten emelkedjen.`,`Lépj puhán.`]},"high-knees":{name:`Futás magas térdemeléssel`,description:`Futás helyben magasra emelt térddel. Fejleszti a szív- és érrendszeri állóképességet és a lábak gyorsaságát.`,steps:[`Állj egyenesen, a lábfejek csípőszélességben.`,`Kezdj el futni helyben, a térdedet nagyjából csípőmagasságig emelve.`,`Dolgoztasd a karodat a lábad ritmusában.`,`Folytasd a megadott ideig.`],warnings:[`Puhán érkezz a talp elülső részére.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben vagy a bokádban.`],techniqueNotes:[`Tartsd függőlegesen a törzsedet.`,`Ne dőlj hátra.`]},"march-in-place":{name:`Menetelés helyben`,description:`Séta helyben aktív karmunkával. Könnyű, ugrás nélküli kardiógyakorlat bemelegítéshez és a pulzus emeléséhez.`,steps:[`Állj egyenesen, a karod behajlítva a könyöknél.`,`Felváltva emeld a térdedet, mintha helyben lépkednél.`,`Dolgoztasd a karodat a lépéseid ritmusában.`,`Tarts egyenletes tempót a megadott ideig.`],warnings:[],techniqueNotes:[`Tartsd egyenesen a hátadat.`,`A nehezítéshez emeld magasabbra a térdedet, vagy gyorsíts a tempón.`]},"mountain-climbers":{name:`Hegymászó`,description:`A térd váltakozó mellkashoz húzása fekvőtámasz helyzetben. Fejleszti az állóképességet és edzi a törzsizmokat.`,steps:[`Vegyél fel fekvőtámasz helyzetet, a tenyered a váll alatt.`,`Húzd a mellkasod felé az egyik térdedet.`,`Told vissza a lábadat, és húzd előre a másik térdedet.`,`Váltogasd a lábakat gyors, de kontrollált tempóban.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a csuklódban vagy a vállaidban.`],techniqueNotes:[`Ne told magasra a csípődet.`,`A válladat tartsd a tenyered fölött.`]},burpee:s,"squat-jump":{name:`Guggolóugrás`,description:`Guggolás robbanékony felugrással. Fejleszti a lábak erejét és a robbanékonyságot.`,steps:[`Állj egyenesen, a lábfejek vállszélességben.`,`Guggolj le kényelmes mélységig.`,`Robbanékonyan ugorj fel.`,`Puhán érkezz, és azonnal térj vissza a guggolásba.`],warnings:[`Puhán, behajlított lábbal érkezz.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben vagy a bokádban.`],techniqueNotes:[`A térd a lábujjak irányába mozog.`,`A landolás halk és kontrollált.`]},"cat-cow":{name:`Macska-tehén`,description:`A hát váltakozó domborítása és homorítása négykézláb. Javítja a gerinc mozgékonyságát.`,steps:[`Állj négykézlábra, a tenyered a váll alatt.`,`Belégzéskor homorítsd a hátadat, és emeld fel a tekintetedet.`,`Kilégzéskor domborítsd a hátadat, a fejedet leengedve.`,`Ismételd simán, a légzés ritmusában.`],warnings:[`Kényelmes mozgástartományban mozogj, és hagyd abba, ha fájdalmat érzel.`],techniqueNotes:[`A mozgás a csípőtől a fej felé halad.`,`Ne siess.`]},"kneeling-hip-flexor-stretch":{name:`Csípőhajlító nyújtás térdelve`,description:`A comb elülső oldalának nyújtása térdelő kitörés helyzetben. Javítja a csípőízület mozgékonyságát.`,steps:[`Térdelj fél térdre, a másik láb elöl derékszögben behajlítva.`,`Feszítsd meg annak a lábnak a farizmát, amelyik a földön térdel.`,`Simán told előre a csípődet, amíg nyújtást nem érzel.`,`Tartsd a helyzetet a megadott ideig, majd cserélj lábat.`],warnings:[`Tegyél valami puhát a térded alá; hagyd abba, ha fájdalmat érzel.`],techniqueNotes:[`Ne homorítsd a derekadat.`,`A nyújtás legyen mérsékelt, fájdalom nélkül.`]},"arm-circles":{name:`Karkörzés`,description:`Kinyújtott karok körkörös mozgatása. Átmelegíti a vállízületeket és javítja a mozgékonyságukat.`,steps:[`Állj egyenesen, és tárd oldalra a karodat.`,`Végezz kis köröket a karoddal előre.`,`Fokozatosan növeld a mozgástartományt.`,`Az idő felénél változtass irányt.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban.`],techniqueNotes:[`A váll lent van, ne húzd a füled felé.`,`Simán mozogj.`]},"open-book-rotation":{name:`Nyitott könyv rotáció`,description:`A mellkasi gerinc elfordítása oldalt fekve. Javítja a mellkasi gerinc és a vállak mozgékonyságát.`,steps:[`Feküdj az oldaladra, hajlítsd be a térdedet, a karodat nyújtsd magad elé.`,`Vezesd a felső karodat ívben az ellenkező oldalra, miközben elforgatod a mellkasodat.`,`Kövesd a tekinteteddel a kezedet.`,`Vidd vissza a karodat; a sorozat után cserélj oldalt.`],warnings:[`Kényelmes mozgástartományban mozogj, és hagyd abba, ha fájdalmat érzel.`],techniqueNotes:[`A térded együtt marad a talajon.`,`Lélegezz nyugodtan.`]},"goblet-squat":{name:`Goblet guggolás`,description:`Guggolás súlyzóval vagy kettlebellel a mellkasnál. Edzi a combfeszítőt és a farizmot, és segít függőlegesen tartani a törzset.`,steps:[`Tartsd a súlyzót vagy a kettlebellt függőlegesen a mellkasodnál.`,`Állj egyenesen, a lábfejek kicsit szélesebben a vállnál.`,`Guggolj le, a mellkasodat felemelve tartva.`,`Told fel magad a talpaddal.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben vagy a hátadban.`],techniqueNotes:[`A könyök a térdek között halad.`,`A hát egyenes az egész mozgás alatt.`]},"dumbbell-romanian-deadlift":{name:`Román felhúzás kézisúlyzóval`,description:`Előrehajlás kézisúlyzókkal a csípőízületek mozgásával. Edzi a comb hátsó oldalát és a farizmot.`,steps:[`Állj egyenesen, a kézisúlyzók a combod előtt.`,`Enyhén hajlítsd be a térdedet, és told hátra a csípődet.`,`Ereszd a kézisúlyzókat a lábad mentén, amíg a comb hátsó oldalán nyújtást nem érzel.`,`Térj vissza felfelé, a csípődet előretolva.`],warnings:[`Ne görbítsd a hátadat; olyan súlyt válassz, amellyel megtartod a technikát.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`A hát egyenes, a kézisúlyzók közel a lábadhoz.`,`A mozgás a csípőből indul, nem a hátból.`]},"one-arm-dumbbell-row":{name:`Egykezes súlyzós evezés`,description:`Súlyzóhúzás a derékhoz előredőlve, kézzel megtámaszkodva. Edzi a hátizmokat és a bicepszet.`,steps:[`Dőlj előre, a szabad kezeddel támaszkodj a combodra vagy egy stabil támaszra.`,`Fogd meg a kézisúlyzót, a karod kinyújtva a váll alatt.`,`Húzd a kézisúlyzót a derekadhoz, a könyöködet hátra vezetve.`,`Lassan engedd vissza; a sorozat után cserélj kart.`],warnings:[`Tartsd egyenesen a hátadat; hagyd abba, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`Ne forgasd el a törzsedet húzás közben.`,`Húzd a lapockádat a gerinc felé.`]},"dumbbell-floor-press":{name:`Kézisúlyzós nyomás a padlón fekve`,description:`Kézisúlyzó nyomása felfelé a padlón fekve, korlátozott mozgástartománnyal. Edzi a mellizmot és a tricepszet.`,steps:[`Feküdj hanyatt, hajlítsd be a térdedet, a kézisúlyzók a kezedben a mellkasodnál.`,`Told fel a kézisúlyzókat a mellkasod fölé.`,`Lassan ereszd vissza, amíg a felkarod meg nem érinti a padlót.`,`Ismételd meg a nyomást.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban.`],techniqueNotes:[`A könyök nagyjából 45°-os szöget zár be a törzzsel.`,`Kontrolláltan ereszd a súlyzókat, a padlóra csapódás nélkül.`]},"dumbbell-bench-press":{name:`Kézisúlyzós fekvenyomás padon`,description:`Kézisúlyzó nyomása felfelé vízszintes padon fekve. Edzi a mellizmot és a tricepszet.`,steps:[`Feküdj a padra, a talpad a talajon, a kézisúlyzók a mellkasodnál.`,`Told fel a kézisúlyzókat a mellkasod fölé.`,`Lassan ereszd vissza őket mellkasmagasságig.`,`Ismételd meg a nyomást.`],warnings:[`Olyan súlyt válassz, amelyet kontrolláltan le tudsz ereszteni.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban.`],techniqueNotes:[`A lapockák összehúzva a padhoz szorítva.`,`Ne pattintsd vissza a kézisúlyzókat a mellkasról.`]},"incline-dumbbell-press":{name:`Kézisúlyzós nyomás döntött padon`,description:`Kézisúlyzó nyomása felemelt háttámlájú padon fekve. Edzi a mellizom felső részét és az elülső deltát.`,steps:[`Állítsd a pad háttámláját mérsékelt dőlésszögbe.`,`Ülj le a padra, a hátad a háttámlához szorítva, a kézisúlyzók a mellkasodnál.`,`Told fel a kézisúlyzókat a mellkasod felső része fölé.`,`Lassan ereszd vissza, és ismételd.`],warnings:[`Győződj meg róla, hogy a pad háttámlája biztosan rögzítve van.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban.`],techniqueNotes:[`A lapockák összehúzva a padhoz szorítva.`,`Kontrolláltan mozogj a teljes mozgástartományban.`]},"dumbbell-shoulder-press":{name:`Kézisúlyzós vállnyomás`,description:`Kézisúlyzó nyomása felfelé állva. Edzi a deltaizmot és a tricepszet.`,steps:[`Állj egyenesen, a kézisúlyzók vállmagasságban.`,`Feszítsd meg a hasadat és a farizmodat.`,`Told fel a kézisúlyzókat a fejed fölé.`,`Lassan ereszd vissza vállmagasságig.`],warnings:[`Ne homorítsd a derekadat nyomás közben.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban, a nyakadban vagy a hátadban.`],techniqueNotes:[`A bordák lent, a törzs stabil.`,`Ne told hátra a fejedet.`]},"dumbbell-reverse-lunge":{name:`Hátrafelé kitörés kézisúlyzóval`,description:`Kitörés hátralépéssel, kézisúlyzókkal a kézben. Edzi a combfeszítőt és a farizmot további terheléssel.`,steps:[`Állj egyenesen, a kézisúlyzók a leengedett karodban.`,`Lépj hátra, és ereszkedj le mindkét térded behajlításával.`,`Told el magad az elülső lábaddal, és térj vissza a kiindulóhelyzetbe.`,`Cserélgesd a lábakat, vagy végezd az összes ismétlést az egyik oldalra.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`Tartsd függőlegesen a törzsedet.`,`A váll lent van, a kézisúlyzók nem lengenek.`]},"farmer-carry":{name:`Farmer séta`,description:`Séta kézisúlyzókkal vagy kettlebellekkel a leengedett karban. Edzi a törzsizmokat, a fogóerőt és az általános stabilitást.`,steps:[`Fogj egy-egy kézisúlyzót vagy kettlebellt mindkét kezedbe.`,`Egyenesedj ki, a váll lent és hátrahúzva.`,`Menj rövid, egyenletes léptekkel a megadott ideig.`,`Óvatosan tedd le a súlyt a talajra.`],warnings:[`A súlyt egyenes háttal emeld fel és tedd le.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a hátadban vagy a csuklódban.`],techniqueNotes:[`Ne dőlj a súly irányába.`,`Tartsd feszesen a hasadat.`]},"kettlebell-swing":{name:`Kettlebell lendítés`,description:`Dinamikus kettlebell-lendítés a csípőízületek mozgásával. Fejleszti a farizom és a comb hátsó oldalának erejét és az állóképességet.`,steps:[`Állj egyenesen, a lábfejek kicsit szélesebben a vállnál, a kettlebell előtted.`,`Hajolj előre egyenes háttal, és vidd hátra a kettlebellt a lábad között.`,`Lendületesen told előre a csípődet, hogy a kettlebell mellkasmagasságig emelkedjen.`,`Hagyd, hogy a kettlebell visszaessen, és ismételd a mozdulatot.`],warnings:[`Győződj meg róla, hogy körülötted nincsenek emberek és tárgyak.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`A mozgás a csípőből indul, a kar csak tartja a kettlebellt.`,`A hát egyenes az alsó pontban.`]},"kettlebell-deadlift":{name:`Felhúzás kettlebell-lel`,description:`A kettlebell felemelése a talajról a csípőízületek mozgásával. Edzi a farizmot és a comb hátsó oldalát, és megtanít helyesen emelni.`,steps:[`Állj a kettlebell fölé, a lábfejek csípőszélességben.`,`Told hátra a csípődet, hajlítsd be a térdedet, és fogd meg a kettlebell fogantyúját.`,`Egyenesedj fel, a csípődet előretolva.`,`Ugyanazzal a mozdulattal tedd vissza a kettlebellt a talajra.`],warnings:[`Ne görbítsd a hátadat emelés közben.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`A hát egyenes, a tekintet előre néz.`,`A kettlebell közel a testhez mozog.`]},"band-pull-apart":{name:`Gumiszalag széthúzás`,description:`A gumiszalag széthúzása egyenes karral a mellkas előtt. Edzi a hát felső izmait és a hátsó deltát.`,steps:[`Fogd meg a gumiszalagot mindkét kezeddel vállszélességben a mellkasod előtt.`,`Told szét a karodat oldalra, miközben széthúzod a gumiszalagot.`,`A végpontban húzd össze a lapockádat.`,`Lassan vidd vissza a karodat a kiindulóhelyzetbe.`],warnings:[`A gyakorlat előtt ellenőrizd, hogy a gumiszalag nem sérült-e.`],techniqueNotes:[`A váll lent van, ne húzd a füled felé.`,`A kar szinte egyenes az egész mozgás alatt.`]},"band-row":{name:`Evezés gumiszalaggal`,description:`Rögzített gumiszalag húzása a derékhoz. Edzi a hátizmokat és a bicepszet.`,steps:[`Rögzítsd a gumiszalagot derékmagasságban egy stabil támaszhoz.`,`Fogd meg a végeit, és lépj hátra, amíg feszes nem lesz.`,`Húzd a karodat a derekadhoz, a könyöködet hátra vezetve.`,`Lassan told vissza a karodat előre.`],warnings:[`Ellenőrizd, hogy a rögzítés biztos, és a gumiszalag nem sérült.`],techniqueNotes:[`A végpontban húzd össze a lapockádat.`,`A törzs mozdulatlan, ne dőlj hátra.`]},"band-lat-pulldown":{name:`Lehúzás gumiszalaggal`,description:`A fent rögzített gumiszalag lehúzása a mellkasig. Edzi a széles hátizmot és a bicepszet.`,steps:[`Rögzítsd a gumiszalagot a fejed fölött egy stabil támaszhoz.`,`Fogd meg a végeit, a karod felfelé kinyújtva.`,`Húzd a könyöködet lefelé az oldalad felé, a kezedet közelítve a mellkasodhoz.`,`Lassan told vissza a karodat felfelé.`],warnings:[`Ellenőrizd, hogy a felső rögzítés biztos, és a gumiszalag nem sérült.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban.`],techniqueNotes:[`Húzz lefelé a lapockáddal, mielőtt húzni kezdesz.`,`Ne lengesd a törzsedet.`]},"pull-up":{name:`Húzódzkodás`,description:`A test felhúzása a nyújtón álla magasságáig. Edzi a hátizmokat és a bicepszet.`,steps:[`Fogd meg a nyújtót kicsit szélesebb fogással, mint a válladnál.`,`Lógj ki egyenes karral, a lapockádat lehúzva.`,`Húzd fel magad, amíg az állad a nyújtó fölé nem kerül.`,`Lassan ereszkedj vissza egyenes karig.`],warnings:[`Csak biztosan felszerelt nyújtót használj.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban vagy a csuklódban.`],techniqueNotes:[`Ne lengj, és ne rángasd magad.`,`Kontrolláltan ereszkedj.`]},"dead-hang":{name:`Függeszkedés a nyújtón`,description:`Statikus függeszkedés a nyújtón egyenes karral. Erősíti a fogóerőt és a vállöv izmait.`,steps:[`Fogd meg a nyújtót vállszélességű fogással.`,`Óvatosan lógj ki egyenes karral.`,`Tartsd a helyzetet a megadott ideig, egyenletesen lélegezve.`,`Óvatosan lépj vissza a talajra.`],warnings:[`Csak biztosan felszerelt nyújtót használj.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban vagy a csuklódban.`],techniqueNotes:[`Enyhén feszítsd meg a vállat, ne lógj passzívan.`,`Ne lengj.`]},"hanging-knee-raise":{name:`Térdemelés függésben`,description:`A térd mellkashoz húzása a nyújtón függve. Edzi a hasizmokat és a fogóerőt.`,steps:[`Lógj a nyújtón egyenes karral.`,`Feszítsd meg a hasadat, és húzd a térdedet a mellkasod felé.`,`Tarts ki egy másodpercig.`,`Lassan ereszd le a lábadat lengés nélkül.`],warnings:[`Csak biztosan felszerelt nyújtót használj.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban vagy a derekadban.`],techniqueNotes:[`Rántás és lengés nélkül mozogj.`,`A felső pontban enyhén görbítsd be a medencét.`]},"jump-rope":{name:`Ugrókötelezés`,description:`Ritmikus ugrás a kötél felett. Fejleszti a szív- és érrendszeri állóképességet, a koordinációt és a vádli erejét.`,steps:[`Fogd meg az ugrókötél fogantyúit, a kötél a sarkad mögött.`,`Forgasd a kötelet a csuklódból.`,`Végezz alacsony ugrásokat, amikor a kötél áthalad a lábad alatt.`,`Tarts egyenletes ritmust a megadott ideig.`],warnings:[`Alacsonyan ugorj, és puhán érkezz a talp elülső részére.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben vagy a bokádban.`],techniqueNotes:[`A könyök közel a testhez.`,`A térd enyhén behajlítva.`]},"step-up":{name:`Fellépés emelvényre`,description:`Felmenés egy stabil emelvényre felváltva mindkét lábbal. Edzi a combfeszítőt és a farizmot.`,steps:[`Állj az emelvény elé.`,`Tedd rá az egyik lábad teljes talpát.`,`Told fel magad az emelvényen álló lábaddal.`,`Lassan lépj le és ismételd; a sorozat után cserélj lábat.`],warnings:[`Győződj meg róla, hogy az emelvény stabil és nem csúszik.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`Ne told el magad az alsó lábaddal.`,`A térd a lábujj irányába mozog.`]},"barbell-back-squat":{name:`Guggolás rúddal a háton`,description:`Guggolás a hát felső részén fekvő rúddal. Fejleszti a combfeszítő, a far és az egész test erejét.`,steps:[`Helyezd a rudat a hátad felső részére, és vedd le az állványról.`,`Lépj hátra, a lábfejek vállszélességben vagy kicsit szélesebben.`,`Guggolj le kényelmes mélységig, a hátadat egyenesen tartva.`,`Állj fel, és a sorozat után tedd vissza a rudat az állványra.`],warnings:[`Állítsd be az állvány biztonsági tartóit, és olyan súllyal dolgozz, amelyet kontrollálni tudsz.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben, a hátadban vagy a vállaidban.`],techniqueNotes:[`Minden ismétlés előtt feszítsd meg a törzsedet.`,`A térd a lábujjak irányába mozog.`]},"barbell-deadlift":{name:`Felhúzás rúddal`,description:`A rúd felemelése a talajról álló helyzetig. Fejleszti a comb hátsó oldalának, a farizomnak és a hátnak az erejét.`,steps:[`Állj úgy, hogy a rúd a lábfej közepe fölött legyen.`,`Told hátra a csípődet, hajlítsd be a térdedet, és fogd meg a rudat.`,`Egyenesedj fel, a rudat közel tartva a lábadhoz.`,`Ugyanazzal a mozdulattal tedd vissza a rudat a talajra.`],warnings:[`Ne görbítsd a hátadat; olyan súllyal dolgozz, amelyet kontrollálni tudsz.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`A hát egyenes, a törzs feszes.`,`A lábaddal told a talajt, ne a hátaddal húzz.`]},"cardio-machine-intervals":{name:`Intervallum kardiógépen`,description:`Intervallumos munka szobabiciklin, elliptikus gépen vagy más kardiógépen. Fejleszti a szív- és érrendszeri állóképességet.`,steps:[`Melegíts be néhány percig könnyű tempóban.`,`Növeld a tempót vagy az ellenállást az intervallum megadott idejére.`,`A pihenő alatt folytasd a mozgást könnyű tempóban.`,`Ismételd meg az intervallumot a megadott számú alkalommal.`],warnings:[`Használat előtt olvasd el a gép használati útmutatóját.`,`Lassíts vagy állj meg, ha szédülést vagy fájdalmat érzel.`],techniqueNotes:[`A terhelés legyen érezhető, de kontrollált.`,`Tartsd egyenesen a testtartásodat.`]},"jump-rope-boxer-step":{name:`Boxerlépés ugrókötéllel`,description:`Alacsony ugrások kötéllel, a testsúly váltakozó áthelyezésével az egyik lábról a másikra. Egyszerűbb, mint a páros lábas ugrás.`,steps:[`Fogd meg az ugrókötél fogantyúit, a kötél a sarkad mögött.`,`Forgasd a kötelet a csuklódból.`,`Könnyedén helyezd át a testsúlyodat az egyik lábadról a másikra, mintha helyben lépkednél.`,`Tarts egyenletes ritmust a megadott ideig.`],warnings:[`Alacsonyan ugorj, és puhán érkezz a talp elülső részére.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a bokádban.`],techniqueNotes:[`Csak néhány centiméterre ugorj a talaj fölé.`,`A könyök közel a testhez.`]},"jump-rope-side-to-side":{name:`Ugrókötelezés oldalról oldalra`,description:`Ugrás két lábon, kis balra-jobbra elmozdulással. Több terhelést ad a vádlira és fejleszti a koordinációt.`,steps:[`Fogd meg az ugrókötél fogantyúit, a lábad összezárva.`,`Ugorj át a kötélen, kissé balra elmozdulva.`,`A következő ugrásnál mozdulj jobbra.`,`Tartsd a ritmust, és puhán érkezz.`],warnings:[`Győződj meg róla, hogy elég hely van, és a felület nem csúszik.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben vagy a bokádban.`],techniqueNotes:[`Az elmozdulás kicsi, nem szélesebb a lábfejnél.`,`A térd enyhén behajlítva.`]},"jump-rope-high-knees":{name:`Futás ugrókötéllel`,description:`Futás helyben a kötél felett, térdemeléssel. Intenzív kardiógyakorlat az állóképességért.`,steps:[`Fogd meg az ugrókötél fogantyúit, a kötél a sarkad mögött.`,`Fuss helyben, minden lépésnél átengedve a kötelet a lábad alatt.`,`Emeld a térdedet csípőmagasságig.`,`Tartsd a tempót a megadott ideig.`],warnings:[`Csak bemelegítés után végezd.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben, a csípődben vagy a bokádban.`],techniqueNotes:[`A törzs egyenes, ne dőlj hátra.`,`A landolás puha, a talp elülső részére.`]},"lateral-step-up":{name:`Oldalsó fellépés emelvényre`,description:`Felmenés az emelvényre oldalról. A farizmot és a combizmokat a hagyományos fellépéstől eltérő szögből terheli.`,steps:[`Állj oldalt az emelvényhez, a közelebbi láb rajta.`,`Egyenesítsd ki a lábadat, miközben felmész az emelvényre.`,`Kontrolláltan ereszkedj vissza.`,`Fejezd be a sorozatokat az egyik lábon, majd cserélj lábat.`],warnings:[`Győződj meg róla, hogy az emelvény stabil és nem csúszik.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben vagy a csípődben.`],techniqueNotes:[`A támasztó láb dolgozik, a másik csak érint.`,`A térd nem dől befelé.`]},"step-platform-push-up":{name:`Fekvőtámasz emelvényre támaszkodva`,description:`Fekvőtámasz az emelvényen álló kézzel. A klasszikus fekvőtámasz könnyített változata kezdőknek.`,steps:[`Tedd a kezedet az emelvényre kicsit szélesebben a vállnál, a tested egyenes vonal.`,`Hajlítsd be a könyöködet, miközben a mellkasodat az emelvényhez ereszted.`,`Told el magad, miközben kinyújtod a karodat.`,`Tartsd feszesen a törzsedet.`],warnings:[`Az emelvény legyen stabil, lehetőleg csúszásmentes felületen.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a csuklódban vagy a vállaidban.`],techniqueNotes:[`Ne homorítsd a derekadat.`,`A könyök nagyjából 45°-os szöget zár be a törzzsel.`]},"step-platform-calf-raise":{name:`Lábujjhegyre emelkedés emelvényen`,description:`Lábujjhegyre emelkedés az emelvény széléről a nagyobb mozgástartományért. Erősíti a vádliizmokat.`,steps:[`Állj az emelvény szélére a talpad elülső részével, a sarkad a levegőben.`,`Lassan ereszd a sarkadat az emelvény szintje alá.`,`Emelkedj a lehető legmagasabbra lábujjhegyre.`,`Ismételd rántás nélkül.`],warnings:[`Az egyensúlyhoz kapaszkodj a falba vagy egy támaszba.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a bokádban vagy az Achilles-ínban.`],techniqueNotes:[`A mozgás lassú: 2 másodperc fel, 2 le.`,`A térd majdnem egyenes.`]},"step-platform-reverse-lunge":{name:`Hátrafelé kitörés emelvényről`,description:`Hátralépés az emelvényről kitörésbe. Nagyobb mozgástartomány a farizomnak és a combnak.`,steps:[`Állj az emelvényre, a lábfejek csípőszélességben.`,`Lépj az egyik lábaddal hátra a talajra.`,`Ereszkedj kitörésbe, az elülső láb az emelvényen marad.`,`Térj vissza a kiindulóhelyzetbe, és cserélj lábat.`],warnings:[`Győződj meg róla, hogy az emelvény stabil és nem csúszik.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`A törzs függőleges.`,`Az elülső sarok az emelvényhez szorítva.`]},"step-platform-taps":{name:`Emelvény érintés`,description:`Gyors, váltakozó érintések az emelvényen a lábfejekkel. Könnyű kardiógyakorlat bemelegítéshez és állóképességhez.`,steps:[`Állj az emelvény elé.`,`Érintsd meg az emelvényt a jobb lábfejeddel, majd a ballal.`,`Mozogj gyorsan és könnyedén, anélkül hogy teljes talppal lépnél rá.`,`Tartsd a ritmust a megadott ideig.`],warnings:[`Az emelvény legyen stabil.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`A hát egyenes, a kar a ritmusban dolgozik.`,`A mozdulatok könnyűek, ütés nélkül.`]},"bench-dip":{name:`Tricepsz mélybehajlás padon`,description:`Tricepszre ható mélybehajlás a hátad mögötti padra támaszkodva.`,steps:[`Ülj a pad szélére, a kezed a combod mellett.`,`Csúsztasd előre a testedet, a pad szélébe kapaszkodva.`,`Hajlítsd be a könyöködet nagyjából 90°-ig.`,`Nyújtsd ki a karodat, és told fel magad.`],warnings:[`Ne ereszkedj mélyre, ha kényelmetlenséget érzel a vállaidban.`,`A pad álljon stabilan.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban vagy a csuklódban.`],techniqueNotes:[`A könyök hátrafelé mutat, nem oldalra.`,`Ne húzd a válladat a füled felé.`]},"bulgarian-split-squat":{name:`Bolgár guggolás`,description:`Egylábas guggolás a hátsó lábbal a padon. Erősen terheli a farizmot és a combot.`,steps:[`Állj háttal a padnak, és tedd az egyik lábfej felső részét a padra.`,`Ereszkedj le az elülső lábad behajlításával.`,`Told fel magad az elülső láb sarkával.`,`Végezd el az összes ismétlést, majd cserélj lábat.`],warnings:[`A pad legyen stabil; olyan távolságot válassz, hogy a térd ne lépje túl a lábfejet.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben vagy a csípődben.`],techniqueNotes:[`A törzs enyhén előredől.`,`A fő súly az elülső lábon van.`]},"bench-hip-thrust":{name:`Csípőemelés padról`,description:`A csípő felemelése a pad szélére támaszkodó lapockával. A farizom alapgyakorlata.`,steps:[`Ülj a talajra háttal a padnak, a lapockád a pad szélén.`,`Hajlítsd be a térdedet, a talpad a talajon.`,`Told fel a csípődet, amíg a törzsed és a combod egy vonalba nem kerül.`,`Tarts ki egy pillanatig, majd ereszkedj vissza.`],warnings:[`A pad legyen mozdulatlan, lehetőleg a fal mellett.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`Az állad kissé a mellkasodhoz szorítva.`,`Fent ne homorítsd a derekadat.`]},"chest-supported-dumbbell-row":{name:`Súlyzós evezés mellkasi támasszal`,description:`Kézisúlyzók húzása döntött padon mellkassal fekve. Tehermentesíti a derekat, és a terhelést a hátra összpontosítja.`,steps:[`Feküdj mellkassal a padra, mindkét kezedben egy kézisúlyzó.`,`Húzd a kézisúlyzókat a törzsed oldalához, miközben összehúzod a lapockádat.`,`Tarts ki egy pillanatig.`,`Kontrolláltan ereszd vissza a kézisúlyzókat.`],warnings:[`A pad álljon stabilan.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban.`],techniqueNotes:[`A fej a gerinc vonalát folytatja.`,`Ne lengesd a törzsedet.`]},"kettlebell-single-arm-row":{name:`Egykezes evezés kettlebell-lel`,description:`Kettlebell húzása előredőlve, a szabad kézzel megtámaszkodva. Erősíti a hátat és a bicepszet.`,steps:[`Dőlj előre egyenes háttal, a szabad kezeddel támaszkodj a combodra.`,`Fogd meg a kettlebellt a másik kezeddel.`,`Húzd a kettlebellt a derekadhoz, összehúzva a lapockádat.`,`Lassan ereszd vissza a kettlebellt.`],warnings:[`Tartsd egyenesen a hátadat.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`A könyök a törzs mentén mozog.`,`A tekintet a talajra irányul.`]},"kettlebell-overhead-press":{name:`Kettlebell nyomás a fej fölé`,description:`Kettlebell nyomása állva, egy kézzel. Erősíti a vállat, a tricepszet és a törzset.`,steps:[`Emeld a kettlebellt a válladhoz, a könyök a törzshöz szorítva.`,`Feszítsd meg a hasadat és a farizmodat.`,`Nyújtsd ki a karodat a fejed fölé.`,`Lassan told vissza a kettlebellt a válladhoz.`],warnings:[`Győződj meg róla, hogy fölötted elég hely van.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban, a nyakadban vagy a derekadban.`],techniqueNotes:[`Ne homorítsd a derekadat.`,`A csukló egyenes, a kettlebell az alkaron fekszik.`]},"kettlebell-halo":{name:`Halo kettlebell-lel`,description:`A kettlebell körkörös mozgatása a fej körül. Átmelegíti a vállakat és a törzs stabilitására hat.`,steps:[`Állj egyenesen, tartsd a kettlebellt fejjel lefelé a mellkasodnál.`,`Vezesd a kettlebellt a fejed körül az egyik irányba.`,`Vidd vissza a mellkasodhoz.`,`Ismételd a másik irányba.`],warnings:[`Használj könnyű kettlebellt.`,`Tartsd erősen a kettlebellt, hogy ne üsd meg magad.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban vagy a nyakadban.`],techniqueNotes:[`A törzs mozdulatlan, csak a kar dolgozik.`,`A könyök közel a fejhez.`]},"kettlebell-sumo-deadlift":{name:`Szumó felhúzás kettlebell-lel`,description:`Kettlebell húzása széles terpeszben. Terheli a farizmot és a comb belső oldalát.`,steps:[`Állj széles terpeszbe, a lábujjak kifelé, a kettlebell a lábfejek között.`,`Told hátra a csípődet, és fogd meg a kettlebellt.`,`Egyenesedj fel, a lábaddal nyomva a talajt.`,`Lassan tedd vissza a kettlebellt.`],warnings:[`Ne görbítsd a hátadat.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban vagy a csípődben.`],techniqueNotes:[`A térd a lábujjak irányába mozog.`,`A hát egyenes az egész mozgás alatt.`]},"kettlebell-reverse-lunge":{name:`Hátrafelé kitörés kettlebell-lel`,description:`Hátrafelé kitörés kettlebell-lel a mellkasnál. További terhelést ad a lábnak és a farizomnak.`,steps:[`Tartsd a kettlebellt a mellkasodnál mindkét kezeddel.`,`Lépj hátra, és ereszkedj kitörésbe.`,`Told el magad az elülső lábaddal, és térj vissza.`,`Cserélj lábat.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`A törzs függőleges.`,`Az elülső sarok a talajhoz szorítva.`]},"band-squat":{name:`Guggolás gumiszalaggal`,description:`Guggolás a lábad alatt lévő gumiszalaggal. A szalag ellenállást ad felálláskor.`,steps:[`Állj a szalag közepére, a végeit tartsd vállmagasságban.`,`Guggolj le, a csípődet hátratolva.`,`Állj fel, kinyújtva a lábadat.`,`Ne engedd el hirtelen a szalagot.`],warnings:[`Ellenőrizd, hogy a szalag nem sérült.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`A térd a lábujjak irányába.`,`A hát egyenes.`]},"band-chest-press":{name:`Mellnyomás gumiszalaggal`,description:`A szalag nyomása magad előtt állva. Edzi a mellet és a tricepszet súlyzók nélkül.`,steps:[`Vezesd a szalagot a hátad mögött a lapockád alatt, a végei a kezedben.`,`Hajlítsd be a könyöködet, a kéz mellmagasságban.`,`Nyújtsd előre a karodat.`,`Lassan térj vissza.`],warnings:[`Ellenőrizd, hogy a szalag nem sérült, és biztosan fekszik a hátad mögött.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban.`],techniqueNotes:[`A könyök kicsit a váll alatt.`,`A törzs mozdulatlan.`]},"band-overhead-press":{name:`Vállnyomás gumiszalaggal`,description:`A szalag felfelé nyomása rajta állva. Erősíti a vállat és a tricepszet.`,steps:[`Állj a szalagra, a végeit tartsd vállmagasságban.`,`Nyújtsd ki a karodat a fejed fölé.`,`Lassan ereszd vissza a vállhoz.`,`Ne homorítsd a derekadat.`],warnings:[`Győződj meg róla, hogy fölötted elég hely van.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban vagy a nyakadban.`],techniqueNotes:[`A has feszes.`,`A kar függőlegesen mozog.`]},"band-good-morning":{name:`Előrehajlás gumiszalaggal`,description:`Törzs előrehajlítása egyenes háttal, a szalag a vállon és a lábad alatt. Megtanítja a csípőzsanér mozgást.`,steps:[`Állj a szalagra, a másik végét tedd a válladra.`,`Told hátra a csípődet, miközben egyenes háttal előredöntöd a törzsedet.`,`Ereszkedj, amíg nyújtást nem érzel a comb hátsó oldalán.`,`Egyenesedj fel, a csípődet előretolva.`],warnings:[`Ne görbítsd a hátadat.`,`Ellenőrizd, hogy a szalag biztosan rögzítve van.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`A térd enyhén behajlítva.`,`A tekintet lefelé-előre irányul.`]},"band-bicep-curl":{name:`Bicepszhajlítás gumiszalaggal`,description:`Bicepszhajlítás a szalag ellenállásával.`,steps:[`Állj a szalagra, a végei a kezedben, a tenyér előre.`,`Hajlítsd be a könyöködet, a kezedet a válladhoz emelve.`,`Tarts ki egy pillanatig.`,`Lassan ereszd le a karodat.`],warnings:[`Ellenőrizd, hogy a szalag nem sérült.`],techniqueNotes:[`A könyök az oldalhoz szorítva.`,`A törzs nem lendül.`]},"scapular-pull-up":{name:`Lapocka-húzódzkodás`,description:`A lapockák emelése és leengedése függésben a kar behajlítása nélkül. Előkészíti a vállat a húzódzkodáshoz.`,steps:[`Lógj a nyújtón, a karod egyenes.`,`Told le a válladat, és húzd össze a lapockádat, a testedet néhány centire megemelve.`,`Lassan térj vissza a függésbe.`,`Ne hajlítsd be a könyöködet.`],warnings:[`Csak biztosan felszerelt nyújtót használj.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban vagy a csuklódban.`],techniqueNotes:[`A mozgás kicsi, csak a lapockában van.`,`A test nem leng.`]},"negative-pull-up":{name:`Negatív húzódzkodás`,description:`Lassú leengedés a húzódzkodás felső helyzetéből. Segít megtanulni a húzódzkodást.`,steps:[`Állj egy székre, és fogd meg a nyújtót úgy, hogy az állad fölötte legyen.`,`Vedd el a támaszt.`,`Lassan ereszkedj, amíg a karod ki nem egyenesedik (3–5 másodperc).`,`Térj vissza a székre, és ismételd.`],warnings:[`Csak biztosan felszerelt nyújtót használj.`,`Használj széket a felső helyzet felvételéhez.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban vagy a csuklódban.`],techniqueNotes:[`Kontrolláltan ereszkedj, zuhanás nélkül.`,`A lapockák leengedve maradnak.`]},"chin-up":{name:`Húzódzkodás fordított fogással`,description:`Húzódzkodás a tenyérrel magad felé. Jobban bevonja a bicepszet, mint a hagyományos húzódzkodás.`,steps:[`Fogd meg a nyújtót fordított fogással vállszélességben.`,`Húzd fel magad, amíg az állad a nyújtó fölé nem kerül.`,`Tarts ki egy pillanatig.`,`Lassan ereszkedj vissza függésbe.`],warnings:[`Csak biztosan felszerelt nyújtót használj.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban, a könyöködben vagy a csuklódban.`],techniqueNotes:[`Ne lengj.`,`A könyök lefelé és a törzs felé mozog.`]},"hanging-leg-raise":{name:`Nyújtott lábemelés függésben`,description:`Nyújtott láb emelése a nyújtón függve. A hasizmok nehezebb változata.`,steps:[`Lógj a nyújtón.`,`Feszítsd meg a hasadat, és emeld fel a nyújtott lábadat csípőmagasságig.`,`Tarts ki egy pillanatig.`,`Lassan ereszd le a lábadat.`],warnings:[`Csak biztosan felszerelt nyújtót használj.`,`Ne lengj, a lábadat lassan emeld.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban vagy a derekadban.`],techniqueNotes:[`A medence enyhén alábillentve.`,`A test lengése nélkül.`]},"dumbbell-lateral-raise":{name:`Oldalemelés kézisúlyzóval`,description:`A kézisúlyzók oldalra emelése vállmagasságig. Fejleszti a deltaizom középső részét.`,steps:[`Állj egyenesen, a kézisúlyzók az oldalad mellett.`,`Enyhén hajlítsd be a könyöködet, és emeld oldalra a karodat vállmagasságig.`,`Lassan ereszd le a karodat.`,`Ne húzd a válladat a füled felé.`],warnings:[`Válassz könnyű kézisúlyzókat.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban vagy a nyakadban.`],techniqueNotes:[`A könyök kicsit a csukló fölött.`,`A törzs mozdulatlan.`]},"dumbbell-bicep-curl":{name:`Bicepszhajlítás kézisúlyzóval`,description:`Klasszikus bicepszhajlítás állva.`,steps:[`Állj egyenesen, a kézisúlyzók a leengedett karodban, a tenyér előre.`,`Hajlítsd be a könyöködet, a kézisúlyzókat a válladhoz emelve.`,`Tarts ki egy pillanatig.`,`Lassan ereszd le a kézisúlyzókat.`],warnings:[`Olyan súlyt válassz, amellyel nem kell lengetned a törzsedet.`],techniqueNotes:[`A könyök az oldalhoz szorítva.`,`Ne dőlj hátra.`]},"dumbbell-overhead-triceps-extension":{name:`Francia nyomás kézisúlyzóval`,description:`Karnyújtás kézisúlyzóval a fej mögül. Izolálja a tricepszet.`,steps:[`Állj egyenesen, tartsd a kézisúlyzót mindkét kezeddel a fejed fölött.`,`Hajlítsd be a könyöködet, a kézisúlyzót a fejed mögé eresztve.`,`Nyújtsd ki a karodat felfelé.`,`A könyöködet tartsd közel a fejedhez.`],warnings:[`Tartsd a kézisúlyzót mindkét kezeddel.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban, a könyöködben vagy a nyakadban.`],techniqueNotes:[`A könyök nem nyílik szét oldalra.`,`A has feszes.`]},"dumbbell-sumo-squat":{name:`Szumó guggolás kézisúlyzóval`,description:`Guggolás széles terpeszben, a kézisúlyzó a lábak között. A hangsúly a farizmon és a comb belső oldalán van.`,steps:[`Állj széles terpeszbe, a lábujjak kifelé, a kézisúlyzót tartsd mindkét kezeddel lent.`,`Guggolj le, a térd a lábujjak irányába.`,`Állj fel, a lábaddal nyomva a talajt.`,`Tartsd függőlegesen a törzsedet.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben vagy a csípődben.`],techniqueNotes:[`A hát egyenes.`,`A térd nem dől befelé.`]},"dumbbell-glute-bridge":{name:`Farizomhíd kézisúlyzóval`,description:`Farizomhíd a csípőn fekvő kézisúlyzóval. Több terhelést ad a farizomnak.`,steps:[`Feküdj hanyatt, a térded behajlítva, a kézisúlyzó a csípődön.`,`Told fel a csípődet, egy vonalba egyenesítve a testedet.`,`Tarts ki egy pillanatig.`,`Lassan ereszkedj vissza.`],warnings:[`Tartsd erősen a kézisúlyzót.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`Ne homorítsd a derekadat.`,`A sarok a talajhoz szorítva.`]},"dumbbell-bent-over-row":{name:`Súlyzós evezés előredőlve`,description:`Két kézisúlyzó húzása a derékhoz előredőlve. Erősíti a hátat és a bicepszet.`,steps:[`Dőlj előre egyenes háttal, a kézisúlyzók a leengedett karodban.`,`Húzd a kézisúlyzókat az oldaladhoz, összehúzva a lapockádat.`,`Tarts ki egy pillanatig.`,`Lassan ereszd le a kézisúlyzókat.`],warnings:[`Tartsd egyenesen a hátadat.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`A térd enyhén behajlítva.`,`A könyököt vezesd a törzs mentén.`]},"towel-row":{name:`Evezés törölközővel`,description:`A saját test húzása egy stabil támaszra rögzített törölközőnél. Eszköz nélkül edzi a hátizmokat és a bicepszet.`,steps:[`Hurkolj egy erős törölközőt derékmagasságban egy stabil támasz köré, és fogd meg mindkét végét.`,`Dőlj hátra kinyújtott karral, a lábfejek közelebb a támaszhoz.`,`Húzd a mellkasodat a kezed felé, a könyöködet hátra vezetve.`,`Lassan nyújtsd ki a karodat, és térj vissza a kiindulóhelyzetbe.`],warnings:[`A törölközőt csak stabil támaszra rögzítsd: szilárd oszlopra, korlátra vagy olyan zárt ajtó kilincsére, amely tőled elfelé nyílik.`,`Ellenőrizd, hogy a törölköző erős, és nem csúszik ki a kezedből.`],techniqueNotes:[`Tartsd egyenesen a testedet a fejtől a sarokig.`,`Minél közelebb vannak a lábfejek a támaszhoz, annál nehezebb a gyakorlat.`]},"inverted-table-row":{name:`Evezés az asztal alatt`,description:`Vízszintes húzódzkodás egy erős asztal alatt fekve. Edzi a hátizmokat, a bicepszet és a hátsó deltát.`,steps:[`Feküdj hanyatt az asztal alá úgy, hogy a mellkasod az asztallap széle alatt legyen.`,`Fogd meg az asztallap szélét vállszélességű fogással.`,`Feszítsd meg a hasadat és a farizmodat, és húzd a mellkasodat az asztal széléhez.`,`Lassan ereszkedj vissza, teljesen kinyújtva a karodat.`],warnings:[`Csak olyan nehéz, stabil asztalt használj, amely nem borul fel, és elbírja a súlyodat.`,`Az asztallap szélét fogd, ne az üveget vagy a törékeny elemeket.`],techniqueNotes:[`A test egyenes a vállaktól a sarokig, a csípő nem lóg le.`,`A gyakorlat könnyítéséhez hajlítsd be a térdedet, és tedd a talpadat a talajra.`]},"prone-y-t-w-raise":{name:`Y-T-W karemelés hasonfekve`,description:`Karemelés három helyzetben hasra fekve. Edzi a hát felső részét és a lapockák stabilizátorait.`,steps:[`Feküdj hasra, a homlokod a talaj fölött, a karod előre nyújtva.`,`Emeld fel a karodat Y betű alakban, tarts ki egy másodpercig, és ereszd le.`,`Told szét a karodat oldalra T betű alakban, emeld fel és ereszd le.`,`Hajlítsd be a könyöködet W betű alakban, húzd össze a lapockádat, emeld fel és ereszd le a karodat. Ez egy ismétlés.`],warnings:[`Ne told hátra a fejedet.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban vagy a nyakadban.`],techniqueNotes:[`A mozgás a lapockából indul, nem a derékból.`,`A hüvelykujjak felfelé néznek.`]},"reverse-snow-angel":{name:`Fordított hóangyal`,description:`Simán mozgó karkörzés a csípőtől a fejig hasra fekve. Edzi a hát felső részét és a váll mozgékonyságát.`,steps:[`Feküdj hasra, a karod a test mellett, a tenyér a csípő felé.`,`Emeld fel a karodat a talaj fölé, és húzd össze a lapockádat.`,`Lassan vezesd a karodat ívben oldalra egészen a fejedig.`,`Ugyanazon az úton vidd vissza a karodat a csípődhöz, a talajt nem érintve.`],warnings:[`Ne told hátra a fejedet.`,`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban vagy a nyakadban.`],techniqueNotes:[`Tartsd a karodat végig kicsit a talaj fölött.`,`A derekadat ne homorítsd, a farizom feszes.`]},"leg-press":{name:`Lábtoló gép`,description:`A platform nyomása lábbal ülve. Edzi a combfeszítőt és a farizmot a gerinc terhelése nélkül, kezdőknek is megfelelő.`,steps:[`Ülj be a gépbe, a derekad a háttámlához szorítva, a lábfejek a platformon vállszélességben.`,`Old ki a biztosítókat, és lassan hajlítsd be a térdedet kényelmes mélységig.`,`Kilégzéssel nyújtsd ki a lábadat, a térdet teljesen kiegyenesítés nélkül.`,`A sorozat végén tedd vissza a biztosítókat a helyükre.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`A derék nem válik el a háttámlától.`,`A térd a lábujjak irányába mozog.`]},"machine-chest-press":{name:`Mellnyomó gép`,description:`A fogantyúk nyomása a mellkastól ülve. Biztonságosan megtanítja a nyomómozdulatot, és edzi a mellet, a vállat és a tricepszet.`,steps:[`Állítsd be az ülést úgy, hogy a fogantyúk a mellkasod közepének magasságában legyenek.`,`Fogd meg a fogantyúkat, és szorítsd a lapockádat a háttámlához.`,`Kilégzéssel told előre a karodat, a könyöködet teljesen ki nem zárva.`,`Lassan told vissza a fogantyúkat, érezve a mellkas nyúlását.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban.`],techniqueNotes:[`A váll nem emelkedik a füled felé.`]},"machine-shoulder-press":{name:`Vállnyomó gép`,description:`Függőleges nyomás ülve a gépben. Edzi a vállat és a tricepszet, a hát támasza mellett.`,steps:[`Állítsd be az ülést úgy, hogy a fogantyúk vállmagasságban legyenek.`,`Szorítsd a hátadat a háttámlához, és fogd meg a fogantyúkat.`,`Kilégzéssel told fel a karodat.`,`Lassan ereszd vissza a fogantyúkat vállmagasságig.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban.`],techniqueNotes:[`Ne homorítsd a derekadat.`]},"seated-cable-row":{name:`Ülő csigás evezés`,description:`A csiga fogantyújának vízszintes húzása. Edzi a hátat és a hátsó deltát, megtanítja a lapockák összehúzását.`,steps:[`Ülj le, tedd a lábfejedet a támaszokra, és fogd meg a fogantyút egyenes háttal.`,`Húzd a fogantyút a hasadhoz, összehúzva a lapockádat.`,`Tarts ki egy pillanatig a végpontban.`,`Lassan told vissza a karodat előre, a hátadat nem görbítve.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`A törzs szinte mozdulatlan.`,`A könyök a test mentén mozog.`]},"lat-pulldown-machine":{name:`Lehúzógép`,description:`Széles fogantyú húzása a mellkasig ülve. Előkészít a húzódzkodásra, és edzi a széles hátizmot.`,steps:[`Rögzítsd a combodat a párnák alatt, és fogd meg a fogantyút a válladnál szélesebben.`,`Dőlj kissé hátra, és húzd a fogantyút a mellkasod felső részéhez.`,`Húzd össze a lapockádat, és tarts ki egy pillanatig.`,`Lassan told vissza a fogantyút felfelé.`],warnings:[],techniqueNotes:[`A könyökeddel húzz, ne a kezeddel.`]},"leg-curl-machine":{name:`Lábhajlító gép`,description:`Izolált lábhajlítás fekve vagy ülve. Edzi a comb hátsó oldalát.`,steps:[`Állítsd be a párnát úgy, hogy a sarkad fölött legyen.`,`Kilégzéssel hajlítsd be a lábadat, a sarkadat a farizmod felé húzva.`,`Tarts ki egy pillanatig a felső pontban.`,`Lassan nyújtsd ki a lábadat.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`A csípő nem emelkedik el a paddal.`]},"leg-extension-machine":{name:`Lábfeszítő gép`,description:`Izolált lábfeszítés ülve. Edzi a combfeszítőt.`,steps:[`Állítsd be a háttámlát és a párnát a lábszárad fölött.`,`Kilégzéssel nyújtsd ki a lábadat.`,`Tarts ki egy pillanatig a felső pontban.`,`Lassan ereszd le a lábadat.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`A mozdulatok simák, rántás nélkül.`]},"cable-triceps-pushdown":{name:`Tricepsz letolás csigán`,description:`A karok lefelé nyújtása a felső csigán. Izoláltan edzi a tricepszet.`,steps:[`Állj a csiga elé, fogd meg a fogantyút, a könyök az oldalhoz szorítva.`,`Kilégzéssel nyújtsd ki lefelé a karodat.`,`Tarts ki egy pillanatig lent.`,`Lassan told vissza a fogantyút mellmagasságig.`],warnings:[],techniqueNotes:[`A könyök nem mozog.`]},"cable-biceps-curl":{name:`Bicepszhajlítás alsó csigán`,description:`Bicepszhajlítás állva az alsó csiga mellett. Izoláltan edzi a bicepszet.`,steps:[`Állj az alsó csiga elé, fogd meg a fogantyút tenyérrel felfelé.`,`Kilégzéssel hajlítsd be a karodat a válladig.`,`Tarts ki egy pillanatig fent.`,`Lassan nyújtsd ki a karodat.`],warnings:[],techniqueNotes:[`A könyök az oldalhoz szorítva, a törzs mozdulatlan.`]},"cable-face-pull":{name:`Arcmagasságú húzás kötéllel`,description:`A kötélfogantyú húzása arcmagasságig. Erősíti a hátsó deltát és a lapockák közötti izmokat, hasznos a testtartáshoz.`,steps:[`Rögzítsd a kötelet a csigán arcmagasságban, és lépj hátra egy lépést.`,`Húzd a kötelet az arcod felé, a könyöködet oldalra szélesen tartva.`,`Húzd össze a lapockádat, és tarts ki egy pillanatig.`,`Lassan told vissza a karodat előre.`],warnings:[],techniqueNotes:[`A súly könnyű, a mozgás kontrollált.`]},"cable-woodchop":{name:`Favágás csigán`,description:`A törzs átlós forgatása a csiga fogantyújával. Edzi a ferde hasizmokat, és megtanítja az erőátvitelt a törzsön keresztül.`,steps:[`Állj oldalt a csigához, fogd meg a fogantyút két kézzel.`,`Húzd a fogantyút átlósan lefelé, miközben elforgatod a törzsedet.`,`Tartsd a karodat majdnem egyenesen, a mellkasoddal forogj.`,`Lassan told vissza a fogantyút és ismételd, majd cserélj oldalt.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`A törzseddel mozogj, ne csak a karoddal.`]},"barbell-bench-press":{name:`Fekvenyomás rúddal`,description:`Klasszikus rúdnyomás vízszintes padon. A mell, a váll és a tricepsz alapgyakorlata.`,steps:[`Feküdj a padra, a talpad a talajon, a lapockád összehúzva, a szemed a rúd alatt.`,`Vedd le a rudat, és ereszd a mellkasod közepéig.`,`Kilégzéssel told a rudat felfelé, amíg a karod ki nem egyenesedik.`,`A sorozat végén tedd vissza a rudat az állványra.`],warnings:[`Teremben ne nyomj rudat biztosítás nélkül, és hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban.`],techniqueNotes:[`Legyen melletted segítő, vagy használj biztonsági tartókat.`,`A csukló a könyök fölött.`]},"barbell-bent-over-row":{name:`Evezés rúddal előredőlve`,description:`A rúd húzása a hasig előredőlve. Edzi az egész hátat, a hátsó deltát és a bicepszet.`,steps:[`Állj vállszélességben, fogd meg a rudat a válladnál kicsit szélesebb fogással.`,`Dőlj előre egyenes háttal, a térd enyhén behajlítva.`,`Húzd a rudat a hasad alsó részéhez.`,`Lassan ereszd vissza a rudat, a hátadat nem görbítve.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`A hát egyenes az egész mozgás alatt.`]},"barbell-overhead-press":{name:`Vállnyomás rúddal állva`,description:`Rúdnyomás a fej fölé állva. Fejleszti a váll és a hát felső részének erejét, stabil törzset igényel.`,steps:[`Fogd meg a rudat kulcscsontmagasságban, a válladnál kicsit szélesebb fogással.`,`Feszítsd meg a hasadat és a farizmodat, és kilégzéssel told fel a rudat.`,`A végén a fejed kicsit előre kerül, a rúd a lábfej közepe fölött van.`,`Lassan ereszd a rudat a kulcscsontodig.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban vagy a derekadban.`],techniqueNotes:[`Ne homorítsd a derekadat.`]},"barbell-romanian-deadlift":{name:`Román felhúzás rúddal`,description:`Felhúzás kinyújtott lábbal. Edzi a comb hátsó oldalát és a farizmot, megtanítja a csípő hátratolásával járó mozgást.`,steps:[`Állj a rúddal a kezedben, a térd enyhén behajlítva.`,`Told hátra a csípődet, a rudat a lábad mentén vezetve.`,`Ereszd a térd alá, egyenes hátat tartva.`,`Kilégzéssel térj vissza a kiindulóhelyzetbe, a csípődet előretolva.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a derekadban.`],techniqueNotes:[`A mozgás a csípőből indul, nem a hátból.`]},"treadmill-incline-walk":{name:`Emelkedős séta futópadon`,description:`Gyors séta emelkedővel beállított futópadon. Ugrás nélküli kardióterhelés az állóképességnek és a lábaknak.`,steps:[`Állíts be 4–8%-os emelkedést és kényelmes, gyors sétatempót.`,`Tartsd egyenesen a törzsedet, ne támaszkodj a korlátra.`,`Menj állandó tempóban a szükséges ideig.`,`A végén csökkentsd a sebességet és az emelkedést a regenerálódáshoz.`],warnings:[],techniqueNotes:[`A légzés egyenletes marad, rövid mondatokban tudsz beszélni.`]},"easy-run-intervals":{name:`Könnyű futás intervallumokban`,description:`Nyugodt futás és séta váltogatása. Fejleszti a szív és a légzés állóképességét hirtelen terhelés nélkül.`,steps:[`Melegíts be egy percig gyors sétával.`,`Fuss kényelmes tempóban a megadott ideig.`,`Térj át sétára a regenerálódáshoz.`,`Ismételd a váltogatást a megadott számú sorozatban.`],warnings:[`Hagyd abba a futást, ha fájdalmat érzel a bokádban vagy a térdedben.`],techniqueNotes:[`A tempó lehetővé teszi, hogy orron át lélegezz vagy rövid mondatokban beszélj.`]},"sprint-intervals":{name:`Sprint gyorsítások`,description:`Rövid, teljes sebességű gyorsítások teljes pihenővel. Fejlesztik az erőt és a sebesség-állóképességet.`,steps:[`Alaposan melegíts be, és futj le néhány könnyű gyorsítást.`,`Gyorsíts a maximum nagyjából 90%-ának megfelelő sebességre.`,`A gyorsítás után sétálva térj vissza, és teljesen pihend ki magad.`,`Ismételd a megadott számú sorozatban.`],warnings:[`Ne végezd csúszós felületen, és hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben vagy a bokádban.`],techniqueNotes:[`Dőlj előre a törzseddel, és dolgoztasd a karodat.`]},"brisk-walk-intervals":{name:`Gyors séta intervallumokban`,description:`Gyors és nyugodt séta váltogatása a szabadban. Kezdéshez és regenerálódáshoz is jó.`,steps:[`Menj nyugodtan egy percig bemelegítésként.`,`Menj gyorsan, behajlított karral lendítve.`,`Térj át nyugodt lépésre a regenerálódáshoz.`,`Ismételd a váltogatást.`],warnings:[],techniqueNotes:[`Gyors lépés: a légzés felgyorsul, de még tudsz beszélni.`]},"walking-lunge":{name:`Járó kitörés`,description:`Kitörések előrehaladással. Edzik a lábat és a farizmot, és tanítják az egyensúlyt.`,steps:[`Állj egyenesen, a kezed a derekadon vagy a test mellett.`,`Lépj előre egy nagy lépést, és ereszkedj le mindkét térdedet 90°-ig behajlítva.`,`Told el magad az elülső lábaddal, és húzd a hátsót az elülső lépéshez.`,`Folytasd, a lábakat váltogatva.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`Az elülső térd a boka fölött.`]},"bear-crawl":{name:`Medvejárás`,description:`Mozgás négy támaszponton, felemelt térddel. Erősíti a vállat, a törzset és a lábat, fejleszti a koordinációt.`,steps:[`Állj a tenyeredre és a lábfejedre, a térd 5 cm-re a talaj fölött.`,`Egyszerre lépj előre az ellentétes karral és lábbal.`,`Tartsd egyenesen a hátadat, a csípőt alacsonyan.`,`Mozogj a megadott ideig, majd ugyanígy hátra.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a csuklódban.`],techniqueNotes:[`A mozdulatok lassúak és kontrolláltak.`]},"broad-jump":{name:`Távolugrás helyből`,description:`Robbanékony ugrás előre két lábról. Fejleszti a láb erejét és a koordinációt.`,steps:[`Állj vállszélességben, a karodat told hátra.`,`Told el magad, a karodat előre lendítve, és ugorj minél messzebbre.`,`Puhán érkezz behajlított térddel.`,`Állj meg, nyerd vissza az egyensúlyodat, és ismételd.`],warnings:[`Ne végezd csúszós felületen, és hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`Puha landolás a teljes talpra.`]},"skater-jumps":{name:`Korcsolyázó ugrások`,description:`Oldalirányú ugrások lábról lábra. Edzik az egyensúlyt, a lábat és az állóképességet.`,steps:[`Állj az egyik lábadra, a másikat told hátra.`,`Ugorj oldalra a másik lábadra, a karodat lendítve.`,`Állj meg egy pillanatra, megtartva az egyensúlyod.`,`Ugorj vissza, és folytasd a megadott ideig.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben vagy a bokádban.`],techniqueNotes:[`Puha landolás, a térd nem megy túl a lábujjon.`]},"shuttle-run":{name:`Ingafutás`,description:`Futás két pont között irányváltással. Fejleszti a reakciósebességet és az állóképességet.`,steps:[`Jelölj meg két pontot egymástól 3 m távolságra.`,`Fuss a második pontig, és érintsd meg a talajt a kezeddel.`,`Gyorsan fordulj meg, és fuss vissza.`,`Ismételd a megadott ideig.`],warnings:[`Ne végezd csúszós felületen.`],techniqueNotes:[`Behajlított térddel fordulj, a láb nem lép ki oldalra.`]},"stair-climb":{name:`Lépcsőmászás`,description:`Gyors felmenés lépcsőn vagy meredek lejtőn. Kardió, a láb és a far edzése.`,steps:[`Állj a lépcső vagy a lejtő aljához.`,`Menj fel gyors léptekkel, a lépcsőfokra a teljes talpat téve.`,`Menj felfelé a megadott ideig, majd lassan ereszkedj le.`,`Ismételd a megadott számú sorozatban.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`A lemenet nyugodt, szükség esetén kapaszkodj a korlátba.`]},"park-bench-step-up":{name:`Fellépés parkpadra`,description:`Fellépés egy stabil padra egy lábbal. Edzi a combfeszítőt és a farizmot.`,steps:[`Ellenőrizd, hogy a pad stabil, és állj elé.`,`Tedd az egyik lábfejedet a padra, és emelkedj fel a lábad kinyújtásával.`,`Lassan lépj le, kontrollálva a mozgást.`,`Fejezd be a sorozatot, és cserélj lábat.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a térdedben.`],techniqueNotes:[`A padon álló lábbal told magad, ne a talajról lökd el magad.`]},"park-bench-incline-push-up":{name:`Fekvőtámasz parkpadnál`,description:`Fekvőtámasz a padra támaszkodó kézzel. Könnyített változat a mellnek, a vállnak és a tricepsznek.`,steps:[`Tedd a tenyeredet egy stabil pad szélére, a tested egy vonalban.`,`Hajlítsd be a könyöködet, és ereszd a mellkasodat a padhoz.`,`Kilégzéssel told el magad, amíg a karod ki nem egyenesedik.`,`Tartsd feszesen a törzsedet az egész mozgás alatt.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a csuklódban.`],techniqueNotes:[`A könyök nagyjából 45°-os szöget zár be a törzzsel.`]},"australian-pull-up":{name:`Evezés alacsony nyújtón`,description:`A test húzása egy alacsony rúdhoz alatta fekve. Edzi a hátat és a bicepszet, könnyebb a húzódzkodásnál.`,steps:[`Állj egy alacsony, erős rúd alá, és fogd meg a válladnál szélesebb fogással.`,`Nyújtsd egyenes vonalba a testedet, a sarkad a talajon.`,`Húzd a mellkasodat a rúdhoz, összehúzva a lapockádat.`,`Lassan ereszkedj vissza majdnem egyenes karig.`],warnings:[`Győződj meg róla, hogy a rúd erős, és hagyd abba a gyakorlatot, ha fájdalmat érzel a vállaidban.`],techniqueNotes:[`A test egyenes marad, a csípő nem lóg le.`]},"outdoor-plank-shoulder-taps":{name:`Plank vállérintéssel`,description:`Plank a váll váltakozó érintésével. Edzi a törzset és a váll stabilitását.`,steps:[`Vegyél fel magas plank helyzetet, a lábfejek kicsit szélesebben a vállnál.`,`Érintsd meg a jobb kezeddel a bal vállad, a csípődet nem lengetve.`,`Told vissza a kezedet, és érintsd meg a másikkal.`,`Folytasd a váltogatást a megadott ideig.`],warnings:[`Hagyd abba a gyakorlatot, ha fájdalmat érzel a csuklódban.`],techniqueNotes:[`A csípő szinte nem mozog.`]}};export{s as burpee,d as default,l as plank,t as superman};